CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, client_name TEXT NOT NULL, company TEXT DEFAULT '', expires_at INTEGER NOT NULL, used_at INTEGER, revoked_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS testimonials (id TEXT PRIMARY KEY, invitation_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, company TEXT DEFAULT '', rating INTEGER NOT NULL, quote TEXT NOT NULL, permission TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, reviewed_at INTEGER, FOREIGN KEY(invitation_id) REFERENCES invitations(id));
CREATE INDEX IF NOT EXISTS idx_testimonials_status ON testimonials(status);
